INSERT INTO public.faq_items (question, answer, sort_order, published) VALUES
('Kontrola ojetého vozu v Praze – kolik stojí a co zahrnuje?', 'Kontrola ojetého vozu v Praze a okolí stojí od 2 490 Kč včetně DPH. Cena zahrnuje diagnostiku elektroniky, kontrolu motoru, převodovky, podvozku, karoserie, interiéru i zkušební jízdu. Dopravu do Prahy a Středočeského kraje si můžete spočítat přímo v objednávkovém formuláři – ke vzdálenosti od naší základny se přičte malý příplatek za cestu.', 7, true),
('Jak dlouho trvá kontrola auta před koupí v Praze?', 'Kontrola ojetého vozu v Praze a okolí trvá obvykle 60 až 90 minut. Součástí je technická prohlídka vozu na místě u prodejce i krátká zkušební jízda. Výsledek a doporučení, zda vůz koupit, dostanete okamžitě na místě, písemný protokol s fotografiemi pak e-mailem do 24 hodin.', 8, true),
('Přijedete s kontrolou za prodejcem do Prahy?', 'Ano, přijedeme přímo za vámi – k autobazaru, do servisu nebo na adresu soukromého prodejce v Praze a celém Středočeském kraji (např. Kladno, Mladá Boleslav, Příbram, Beroun, Kolín). Stačí v objednávce uvést lokalitu vozu a my domluvíme termín kontroly na místě.', 9, true),
('Kontrolujete auta i mimo Prahu, ve Středočeském kraji?', 'Ano, kromě Prahy obsluhujeme celý Středočeský kraj a po dohodě i další místa po celé ČR. Ať je vůz v jakémkoli autobazaru nebo u soukromého prodejce, objednejte si kontrolu a přijedeme přímo na místo. Cenu dopravy vám předem spočítá kalkulačka v objednávkovém formuláři.', 10, true),
('Proč si nechat zkontrolovat ojetý vůz před koupí v Praze?', 'Koupě ojetého vozu bez kontroly s sebou nese riziko skrytých závad, stočeného tachometru, poškozeného podvozku či vozu po havárii. Nezávislá kontrola v Praze a okolí odhalí skryté vady dřív, než podepíšete kupní smlouvu – můžete se tak vyhnout opravám za desítky tisíc korun. Detailní protokol využijete i při jednání o slevě.', 11, true),
('Jak objednat kontrolu ojetého vozu v Praze?', 'Objednání je jednoduché: vyplňte objednávkový formulář na této stránce (stačí jméno, e-mail, telefon a lokalita vozu), případně nám zavolejte. Kontaktujeme vás do 24 hodin, domluvíme termín kontroly u prodejce v Praze či okolí a připravíme pro vás cenovou nabídku včetně dopravy.', 12, true);